    assertEquals(0L, gson.<List<Date>>fromJson("[\"1970-01-01\"]", listOfDates).get(0).getTime());
  } finally {
    TimeZone.setDefault(defaultTimeZone);
    Locale.setDefault(defaultLocale);
  }
}

