  public static void main(String[] a) throws Exception {
    Locale.setDefault(Locale.FRANCE);
    for (int s : new int[]{0,1,2,3,4}) {
      SimpleDateFormat d = (SimpleDateFormat) DateFormat.getDateInstance(s);
      SimpleDateFormat t = (SimpleDateFormat) DateFormat.getTimeInstance(s);
      System.out.println(s + " | date: " + d.toPattern() + " | time: " + t.toPattern());
    }
    String pat = ((SimpleDateFormat) DateFormat.getDateInstance(DateFormat.FULL)).toPattern()
        + " " + ((SimpleDateFormat) DateFormat.getTimeInstance(DateFormat.FULL)).toPattern();
    System.out.println("combined: " + pat);
